import pytest

from target import shipping_fee


def test_small_parcel_uses_first_bracket_rate():
    assert shipping_fee(2, [(1, 10), (5, 5)]) == 20


def test_parcel_spanning_brackets_is_billed_per_bracket():
    # 4kg at 10 -> 40, then 1kg at 5 -> 5
    assert shipping_fee(5, [(1, 10), (5, 5)]) == 45


def test_heavier_parcel_keeps_segmenting_brackets():
    # 4kg at 10 -> 40, then 5kg at 5 -> 25
    assert shipping_fee(9, [(1, 10), (5, 5)]) == 65
